+        (r#"{ "orbits": [ { "kind": "spiral", "word": "S" } ] }"#, "spiral"),
+        (r#"{ "orbits": [ { "kind": "circular", "word": " " } ] }"#, "word"),
+        (r#"{ "max_orbit_radius": 0 }"#, "max_orbit_radius"),
