+}
+
+#[test]
+fn the_kind_words_read_and_an_unknown_kind_still_refuses() {
+    for (w, k) in [
+        ("wire_edm", Kind::WireEdm),
+        ("Wire EDM", Kind::WireEdm),
+        ("wedm", Kind::WireEdm),
+        ("sinker_edm", Kind::SinkerEdm),
+        ("die-sinker", Kind::SinkerEdm),
+        ("ram EDM", Kind::SinkerEdm),
