+    assert!(err.contains("wire_edm") && err.contains("sinker_edm"), "{err}");
+    assert!(!posting::post_serves("Fanuc", Kind::WireEdm) && !posting::post_serves("Fanuc Lathe", Kind::SinkerEdm));
+}
+
+fn face() -> OpParams {
+    OpParams::Face {
+        holes: Default::default(),
+        blend_turns: false,
+        tilt: None,
+        stepover: 3.0,
+        clearance_z: Height::fixed(25.0),
