+
+#[test]
+fn a_milling_op_remounted_onto_an_edm_is_refused_at_post() {
+    let (world, mut h) = mill_doc();
+    h.execute(&world, CreateOperation::new(&world, "Face1", TOOL, SrcRef::Stock, face()).expect("face on a mill"));
